def feature_explanations(*, language: str = "tr") -> list[dict[str, Any]]:
    """Return detached bilingual metadata for every existing feature, without execution."""
    if language not in ("tr", "en"):
        raise ValueError("unsupported_language")
    rows = []
    for spec, row in zip(feature_catalog(), _ROWS):
        name, definition_tr, definition_en, purpose_tr, purpose_en, limit_tr, limit_en, units, guide = row
        definition = definition_tr if language == "tr" else definition_en
        purpose = purpose_tr if language == "tr" else purpose_en
        limit = limit_tr if language == "tr" else limit_en
        rows.append(dict(feature_id=spec.feature_id, name=name if language == "tr" else spec.name,
                         definition=definition, purpose=purpose, units=units, limits=limit,
                         explanations=dict(beginner=definition + " " + purpose,
                                           technical=definition + " " + limit,
                                           expert=limit),
                         dependencies=list(spec.dependencies), requirements=list(spec.requirements),
                         executor_modes=list(spec.executor_modes),
                         guide_url="https://github.com/huseyin-dgn/hyso/blob/feature/hyso-models-next/docs/guides/" + guide + ".md"))
    return rows
